-- Fly survey backup
-- Restore with: psql ... < survey_backup.sql
BEGIN;

-- survey_sets: 300 rows

-- survey_set_items: 1500 rows

-- survey_responses: 3 rows

-- survey_rankings: 100 rows

-- Reset sequences
SELECT setval('survey_sets_set_id_seq', (SELECT COALESCE(MAX(set_id),1) FROM survey_sets));
SELECT setval('survey_set_items_item_id_seq', (SELECT COALESCE(MAX(item_id),1) FROM survey_set_items));
SELECT setval('survey_responses_response_id_seq', (SELECT COALESCE(MAX(response_id),1) FROM survey_responses));
SELECT setval('survey_rankings_ranking_id_seq', (SELECT COALESCE(MAX(ranking_id),1) FROM survey_rankings));
COMMIT;
